  1110   * g_uri_parse:
  1111   * @uri_string: a string representing an absolute URI
  1112   * @flags: flags describing how to parse @uri_string
  1113   * @error: #GError for error reporting, or %NULL to ignore.
  1114   *
  1115   * Parses @uri_string according to @flags. If the result is not a
  1116   * valid absolute URI, it will be discarded, and an error returned.
  1117   *
  1118   * Return value: (transfer full): a new #GUri.
  1119   *
  1120   * Since: 2.66
  1121   */
  1122  GUri *
  1123  g_uri_parse (const gchar  *uri_string,
  1124               GUriFlags     flags,
  1125               GError      **error)
  1126  {
  1127    g_return_val_if_fail (uri_string != NULL, NULL);
  1128    g_return_val_if_fail (error == NULL || *error == NULL, NULL);
  1129
  1130    return g_uri_parse_relative (NULL, uri_string, flags, error);
  1131  }
