  1133  /**
  1134   * g_uri_parse_relative:
  1135   * @base_uri: (nullable): a base URI
  1136   * @uri_string: a string representing a relative or absolute URI
  1137   * @flags: flags describing how to parse @uri_string
  1138   * @error: #GError for error reporting, or %NULL to ignore.
  1139   *
  1140   * Parses @uri_string according to @flags and, if it is a relative
  1141   * URI, resolves it relative to @base_uri. If the result is not a
  1142   * valid absolute URI, it will be discarded, and an error returned.
  1143   *
  1144   * Return value: (transfer full): a new #GUri.
  1145   *
  1146   * Since: 2.66
  1147   */
  1148  GUri *
  1149  g_uri_parse_relative (GUri         *base_uri,
  1150                        const gchar  *uri_string,
  1151                        GUriFlags     flags,
  1152                        GError      **error)
  1153  {
  1154    GUri *uri = NULL;
  1155
  1156    g_return_val_if_fail (uri_string != NULL, NULL);
  1157    g_return_val_if_fail (error == NULL || *error == NULL, NULL);
  1158    g_return_val_if_fail (base_uri == NULL || base_uri->scheme != NULL, NULL);
  1159
  1160    uri = g_atomic_rc_box_new0 (GUri);
  1161    uri->flags = flags;
  1162
  1163    if (!g_uri_split_internal (uri_string, flags,
  1164                               &uri->scheme, &uri->userinfo,
  1165                               &uri->user, &uri->password, &uri->auth_params,
  1166                               &uri->host, &uri->port,
  1167                               &uri->path, &uri->query, &uri->fragment,
  1168                               error))
  1169      goto fail;
  1170
  1171    if (!uri->scheme && !base_uri)
  1172      {
  1173        g_set_error_literal (error, G_URI_ERROR, G_URI_ERROR_MISC,
  1174                             _("URI is not absolute, and no base URI was provided"));
  1175        goto fail;
  1176      }
  1177
  1178    if (base_uri)
  1179      {
  1180        /* This is section 5.2.2 of RFC 3986, except that we're doing
  1181         * it in place in @uri rather than copying from R to T.
  1182         */
  1183        if (uri->scheme)
  1184          remove_dot_segments (uri->path);
  1185        else
  1290    resolved_uri_string = g_uri_to_string (resolved_uri);
  1291    g_uri_unref (resolved_uri);
  1292    return resolved_uri_string;
  1293  }
