  1300  #define USER_ALLOWED_CHARS "!$&'()*+,="
  1301  #define PASSWORD_ALLOWED_CHARS "!$&'()*+,=:"
  1302  #define AUTH_PARAMS_ALLOWED_CHARS USERINFO_ALLOWED_CHARS
