  1309  static gchar *
  1310  g_uri_join_internal (GUriFlags    flags,
  1311                       const gchar *scheme,
  1312                       const gchar *user,
  1313                       const gchar *password,
  1314                       const gchar *auth_params,
  1315                       const gchar *host,
  1316                       gint         port,
  1317                       const gchar *path,
  1318                       const gchar *query,
  1319                       const gchar *fragment)
  1320  {
  1321    gboolean encoded = (flags & G_URI_FLAGS_ENCODED);
  1322    GString *str;
  1323
  1324    str = g_string_new (scheme);
  1325    g_string_append_c (str, ':');
  1326
  1327    if (host)
  1328      {
  1329        g_string_append (str, "//");
  1330
  1331        if (user)
  1332          {
  1333            if (encoded)
  1334              g_string_append (str, user);
  1335            else
  1336              {
  1337                /* Encode ':' and ';' regardless of whether we have a
  1338                 * password or auth params, since it may be parsed later
  1339                 * under the assumption that it does.
  1340                 */
  1341                g_string_append_uri_escaped (str, user, USER_ALLOWED_CHARS, TRUE);
  1342              }
  1343
  1344            if (password)
  1345              {
  1346                g_string_append_c (str, ':');
  1347                if (encoded)
  1348                  g_string_append (str, password);
  1349                else
  1350                  g_string_append_uri_escaped (str, password,
  1351                                               PASSWORD_ALLOWED_CHARS, TRUE);
  1352              }
  1353
  1354            if (auth_params)
  1355              {
  1356                g_string_append_c (str, ';');
  1357                if (encoded)
  1358                  g_string_append (str, auth_params);
  1359                else
  1360                  g_string_append_uri_escaped (str, auth_params,
  1361                                               AUTH_PARAMS_ALLOWED_CHARS, TRUE);
  1362              }
  1363
  1364            g_string_append_c (str, '@');
  1365          }
  1366
  1367        if (strchr (host, ':'))
  1368          {
  1369            g_string_append_c (str, '[');
  1370            if (encoded)
  1371              g_string_append (str, host);
  1372            else
  1373              g_string_append_uri_escaped (str, host, IP_ADDR_ALLOWED_CHARS, TRUE);
  1374            g_string_append_c (str, ']');
  1375          }
  1376        else
  1377          {
  1378            if (encoded)
  1379              g_string_append (str, host);
  1380            else
  1381              g_string_append_uri_escaped (str, host, HOST_ALLOWED_CHARS, TRUE);
  1382          }
  1383
  1384        if (port != -1)
  1385          g_string_append_printf (str, ":%d", port);
  1386      }
  1387
  1388    if (encoded)
  1389      g_string_append (str, path);
  1390    else
  1391      g_string_append_uri_escaped (str, path, PATH_ALLOWED_CHARS, TRUE);
  1392
  1393    if (query)
  1394      {
  1395        g_string_append_c (str, '?');
  1396        if (encoded)
  1397          g_string_append (str, query);
  1398        else
  1399          g_string_append_uri_escaped (str, query, QUERY_ALLOWED_CHARS, TRUE);
  1400      }
  1401    if (fragment)
  1402      {
  1403        g_string_append_c (str, '#');
  1404        if (encoded)
  1405          g_string_append (str, fragment);
  1406        else
  1407          g_string_append_uri_escaped (str, fragment, FRAGMENT_ALLOWED_CHARS, TRUE);
  1408      }
